import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class RunnerPolicy {
    static String choose(boolean hasTestNgXml) {
        return hasTestNgXml ? "testng" : "junit5";
    }
}

public class RunnerPolicyTest {
    @Test
    void prefersTestNgWhenXml() {
        assertEquals("testng", RunnerPolicy.choose(true));
    }

    @Test
    void defaultJunit5() {
        assertEquals("junit5", RunnerPolicy.choose(false));
    }
}
